/* Purpose: extracted public DDR/video/IRQ host models for the ARM session.
 * Overview: logical IRQ semantics only; no physical GIC/cache/PHY claim.
 * Revision: 11-14-2026. ZCAM PTS/time map, one engine, physical DDR base zero.
 */
#include "host_platform.h"
#include "host_h264_model.h"
#include "rtlnet_platform.h"
#include "rtlnet_camera.h"
#include "rtlnet_csi2_rx.h"
#include "rtlnet_framebuf.h"
#include "rtlnet_vdma_s2mm.h"
#include "rtlnet_mmio.h"
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define RTLNET_CPU_IRQ_COUNT 2u
#define HOST_DDR_PAGE_BYTES 4096u
#define HOST_DDR_PAGES (RTLNET_PLAT_DDR_SIZE/HOST_DDR_PAGE_BYTES)
static uint32_t *g_ddr_page[HOST_DDR_PAGES];
static uint32_t g_arb_cnt[2][6],g_ddr_and=0xffffffffu,g_reg_acc;
static unsigned g_ddr_alias;
static int g_ddr_arb_on,g_ddr_cal,g_arb_err;
static clock_t g_t0;
#define HOST_VID_VERSION     0x11092026u
#define HOST_VID_FB_OFFSET   0x10000000u   /* DDR3 offset of slot 0 */
#define HOST_VID_SLOTS       3u
#define HOST_VID_SLOT_LOG2   22u
#define HOST_VID_SLOT_BYTES  (1u << HOST_VID_SLOT_LOG2)
#define HOST_VID_PERIOD_RST  33333u
#define HOST_VID_BARS        8u
#define HOST_VID_ERR_FB      (1u << 3)     /* FBUF STATUS.FW_ERR */

static int       g_vid_on;
static uint32_t  g_vid_frames;             /* frames the model has sent */
static uint32_t  g_vid_base;               /* frame count at the last CNT_CLEAR */
static uint32_t  g_csi_mode;
static uint32_t  g_csi_src;
static uint32_t  g_csi_period = HOST_VID_PERIOD_RST;
static uint32_t  g_csi_timeout = RTLNET_CSI2_CAM_TIMEOUT_RESET;
static uint32_t  g_csi_err;                /* STATUS bits [6:2] */
static uint32_t  g_csi_pattern = 4u << RTLNET_CSI2_PATTERN_SPEED_SHIFT;   /* PATTERN reset: static bars, speed 4 */
static uint32_t  g_dma_ctrl = RTLNET_S2MM_CTRL_ENABLE;
static uint32_t  g_dma_stride;
static int       g_fb_holds;
static uint32_t  g_fb_fw_slot;
static uint32_t  g_fb_fw_frame;
static uint32_t  g_fb_fw_mode;
static uint32_t  g_fb_err;
static uint32_t  g_fb_takes;

/* Bar colors: Y, Cb, Cr of white, yellow, cyan, green, magenta, red, blue, black. */
static const uint8_t g_vid_bar[HOST_VID_BARS][3] = {
    { 180u, 128u, 128u }, { 168u, 44u, 136u }, { 145u, 147u, 44u }, { 133u, 63u, 52u },
    { 63u, 193u, 204u }, { 51u, 109u, 212u }, { 28u, 212u, 120u }, { 16u, 128u, 128u }
};

/**
 * @brief DDR3 path model: the arbiter window present, the calibration bit.
 * @param arbiter_present 1 when the arbiter window answers.
 * @param calibrated      1 when CLK_STATUS shows init_calib_complete.
 * @return None.
 */
void host_model_ddr_set(int arbiter_present, int calibrated)
{
    g_ddr_arb_on = arbiter_present;
    g_ddr_cal    = calibrated;
}

/**
 * @brief Empty the memory window, clear the counters, the error flag and the injected faults.
 * @return None.
 */
void host_model_ddr_clear(void)
{
    for (size_t i = 0; i < HOST_DDR_PAGES; i++) {
        free(g_ddr_page[i]);
        g_ddr_page[i] = NULL;
    }
    memset(g_arb_cnt, 0, sizeof(g_arb_cnt));
    g_arb_err   = 0;
    g_ddr_alias = 0u;
    g_ddr_and   = 0xFFFFFFFFu;
}

/**
 * @brief Page of the memory window holding an address.
 * @param addr   Byte address inside the window.
 * @param create 1 allocates a missing page.
 * @return Page (HOST_DDR_PAGE_BYTES / 4 words) or NULL (absent, or outside the window).
 */
static uint32_t *host_ddr_page(uintptr_t addr, int create)
{
    uint32_t off;
    uint32_t idx;
    if (addr - RTLNET_PLAT_DDR_BASE >= RTLNET_PLAT_DDR_SIZE) {
        return NULL;
    }
    off = (uint32_t)(addr - RTLNET_PLAT_DDR_BASE);
    if (g_ddr_alias != 0u) {
        off &= ~(1u << g_ddr_alias);
    }
    idx = off / HOST_DDR_PAGE_BYTES;
    if (g_ddr_page[idx] == NULL && create) {
        g_ddr_page[idx] = (uint32_t *)calloc(HOST_DDR_PAGE_BYTES / 4u, sizeof(uint32_t));
    }
    return g_ddr_page[idx];
}

/**
 * @brief Memory window word index of an address (aliasing applied).
 * @param addr Byte address inside the window.
 * @return Word index inside its page.
 */
static uint32_t host_ddr_word(uintptr_t addr)
{
    uint32_t off = (uint32_t)(addr - RTLNET_PLAT_DDR_BASE);
    if (g_ddr_alias != 0u) {
        off &= ~(1u << g_ddr_alias);
    }
    return (off % HOST_DDR_PAGE_BYTES) / 4u;
}

/**
 * @brief ddrtest host hook: word read from the DDR3 window model.
 * @param addr Byte address.
 * @return Stored word (0 for a never-written word), the injected data mask applied.
 */
uint32_t rtlnet_host_mem_read32(uintptr_t addr)
{
    uint32_t *pg = host_ddr_page(addr, 0);
    g_arb_cnt[0][1]++;
    g_arb_cnt[0][3]++;
    return ((pg != NULL) ? pg[host_ddr_word(addr)] : 0u) & g_ddr_and;
}

/**
 * @brief ddrtest host hook: word write into the DDR3 window model.
 * @param addr  Byte address.
 * @param value Word.
 * @return None.
 */
void rtlnet_host_mem_write32(uintptr_t addr, uint32_t value)
{
    uint32_t *pg = host_ddr_page(addr, 1);
    g_arb_cnt[0][0]++;
    g_arb_cnt[0][2]++;
    if (pg != NULL) {
        pg[host_ddr_word(addr)] = value;
    }
}

/**
 * @brief Present or remove the video cores (the three windows answer 0 when absent).
 * @param present 1 when the windows answer.
 * @return None.
 */
void host_model_video_set(int present)
{
    g_vid_on      = present;
    g_vid_frames  = 0u;
    g_vid_base    = 0u;
    g_csi_mode    = RTLNET_CSI2_MODE_720P30;
    g_csi_src     = RTLNET_CSI2_SRC_AUTO;
    g_csi_period  = HOST_VID_PERIOD_RST;
    g_csi_timeout = RTLNET_CSI2_CAM_TIMEOUT_RESET;
    g_csi_err     = 0u;
    g_csi_pattern = 4u << RTLNET_CSI2_PATTERN_SPEED_SHIFT;
    g_dma_ctrl    = RTLNET_S2MM_CTRL_ENABLE;
    g_dma_stride  = 0u;
    g_fb_holds    = 0;
    g_fb_err      = 0u;
    g_fb_takes    = 0u;
}

/**
 * @brief Set the number of frames the model has sent and published.
 * @param frames Frame count.
 * @return None.
 */
void host_model_video_frames(uint32_t frames)
{
    g_vid_frames = frames;
}

/**
 * @brief Slot a frame was published into.
 * @param frame Frame number (1-based).
 * @return Slot index.
 */
static uint32_t host_vid_slot(uint32_t frame)
{
    return (frame == 0u) ? 0u : ((frame - 1u) % HOST_VID_SLOTS);
}

/**
 * @brief Write the bar frame of a mode into a slot of the memory window, lines at the STRIDE (0 = packed).
 * @param slot Slot index.
 * @param mode VIDEO_MODE value.
 * @return None.
 */
static void host_vid_fill(uint32_t slot, uint32_t mode)
{
    uint32_t w = rtlnet_csi2_rx_mode_width(mode);
    uint32_t h = rtlnet_csi2_rx_mode_height(mode);
    uint32_t stride = (g_dma_stride != 0u) ? g_dma_stride : (w * RTLNET_CSI2_BYTES_PER_PIXEL);
    uintptr_t base = RTLNET_PLAT_DDR_BASE + HOST_VID_FB_OFFSET + ((uintptr_t)slot * HOST_VID_SLOT_BYTES);

    for (uint32_t y = 0u; y < h; y++) {
        for (uint32_t x = 0u; x < w / 2u; x++) {
            uint32_t bar = (x * 2u) / (w / HOST_VID_BARS);
            uint32_t yy = g_vid_bar[bar][0];
            uint32_t word = yy | ((uint32_t)g_vid_bar[bar][1] << 8) | (yy << 16) | ((uint32_t)g_vid_bar[bar][2] << 24);
            uintptr_t a = base + ((uintptr_t)y * stride) + ((uintptr_t)x * 4u);
            uint32_t *pg = host_ddr_page(a, 1);
            if (pg != NULL) {
                pg[host_ddr_word(a)] = word;
            }
        }
    }
}

/**
 * @brief Model of the rtlnet_vdma_s2mm register read mux.
 * @param off Register offset.
 * @return Register value.
 */
static uint32_t host_s2mm_read(uint32_t off)
{
    uint32_t ok = g_vid_frames - g_vid_base;
    uint32_t beats = rtlnet_csi2_rx_mode_height(g_csi_mode) * ((rtlnet_csi2_rx_mode_width(g_csi_mode) * RTLNET_CSI2_BYTES_PER_PIXEL) /
                                                              RTLNET_S2MM_BEAT_BYTES);
    switch (off) {
    case RTLNET_REG_ID:                      return RTLNET_S2MM_ID_VALUE;
    case RTLNET_REG_VERSION:                 return HOST_VID_VERSION;
    case RTLNET_REG_CAPS:                    return RTLNET_S2MM_MAX_BURST_BEATS | (RTLNET_S2MM_BEAT_BYTES << RTLNET_S2MM_CAPS_BYTES_SHIFT) |
                                                    (30u << RTLNET_S2MM_CAPS_ADDR_SHIFT);
    case RTLNET_S2MM_REG_CTRL:               return g_dma_ctrl & RTLNET_S2MM_CTRL_ENABLE;
    case RTLNET_S2MM_REG_STATUS:             return 0u;
    case RTLNET_S2MM_REG_STRIDE:             return g_dma_stride;
    case RTLNET_S2MM_REG_FRAMES_OK:          return ok;
    case RTLNET_S2MM_REG_BURSTS:             return ok * (beats / RTLNET_S2MM_MAX_BURST_BEATS);
    case RTLNET_S2MM_REG_BEATS:              return ok * beats;
    case RTLNET_S2MM_REG_LAST_BASE:          return HOST_VID_FB_OFFSET + (host_vid_slot(g_vid_frames) * HOST_VID_SLOT_BYTES);
    default:                                 return 0u;
    }
}

/**
 * @brief Model of the rtlnet_vdma_s2mm register writes.
 * @param off   Register offset.
 * @param value Value.
 * @return None.
 */
static void host_s2mm_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_S2MM_REG_CTRL) {
        g_dma_ctrl = value & RTLNET_S2MM_CTRL_ENABLE;
        if ((value & RTLNET_S2MM_CTRL_CNT_CLEAR) != 0u) {
            g_vid_base = g_vid_frames;
        }
    } else if (off == RTLNET_S2MM_REG_STRIDE) {
        g_dma_stride = value;
    }
}

/**
 * @brief Model of the rtlnet_framebuf register read mux.
 * @param off Register offset.
 * @return Register value.
 */
static uint32_t host_fb_read(uint32_t off)
{
    uint32_t latest = host_vid_slot(g_vid_frames);
    uint32_t lmode = g_csi_mode;
    switch (off) {
    case RTLNET_REG_ID:                  return RTLNET_FB_ID_VALUE;
    case RTLNET_REG_VERSION:             return HOST_VID_VERSION;
    case RTLNET_REG_CAPS:                return HOST_VID_SLOTS | (1u << RTLNET_FB_CAPS_READERS_SHIFT) |
                                                (HOST_VID_SLOT_LOG2 << RTLNET_FB_CAPS_SLOTLOG2_SHIFT) | (32u << RTLNET_FB_CAPS_ADDR_SHIFT);
    case RTLNET_FB_REG_STATUS:           return ((g_vid_frames != 0u) ? RTLNET_FB_STATUS_LATEST_VALID : 0u) |
                                                (g_fb_holds ? RTLNET_FB_STATUS_FW_HOLDS : 0u) | g_fb_err |
                                                (latest << RTLNET_FB_STATUS_LATEST_SHIFT) | (g_fb_fw_slot << RTLNET_FB_STATUS_FWSLOT_SHIFT);
    case RTLNET_FB_REG_FB_BASE:          return HOST_VID_FB_OFFSET;
    case RTLNET_FB_REG_SLOT_BYTES:       return HOST_VID_SLOT_BYTES;
    case RTLNET_FB_REG_LATEST_BASE:      return HOST_VID_FB_OFFSET + (latest * HOST_VID_SLOT_BYTES);
    case RTLNET_FB_REG_LATEST_FRAME:     return g_vid_frames;
    case RTLNET_FB_REG_LATEST_TS:        return g_vid_frames * g_csi_period;
    case RTLNET_FB_REG_LATEST_WH:        return (rtlnet_csi2_rx_mode_height(lmode) << 16) | rtlnet_csi2_rx_mode_width(lmode);
    case RTLNET_FB_REG_LATEST_SRC:       return 1u;
    case RTLNET_FB_REG_FW_BASE:          return HOST_VID_FB_OFFSET + (g_fb_fw_slot * HOST_VID_SLOT_BYTES);
    case RTLNET_FB_REG_FW_FRAME:         return g_fb_fw_frame;
    case RTLNET_FB_REG_FW_TS:            return g_fb_fw_frame * g_csi_period;
    case RTLNET_FB_REG_FW_WH:            return (rtlnet_csi2_rx_mode_height(g_fb_fw_mode) << 16) | rtlnet_csi2_rx_mode_width(g_fb_fw_mode);
    case RTLNET_FB_REG_FW_SRC:           return 1u;
    case RTLNET_FB_REG_PUBLISHED:        return g_vid_frames - g_vid_base;
    case RTLNET_FB_REG_FW_TAKES:         return g_fb_takes;
    case RTLNET_FB_REG_REFCNT + 0u:      return (g_fb_holds && g_fb_fw_slot == 0u) ? 1u : 0u;
    case RTLNET_FB_REG_REFCNT + 4u:      return (g_fb_holds && g_fb_fw_slot == 1u) ? 1u : 0u;
    case RTLNET_FB_REG_REFCNT + 8u:      return (g_fb_holds && g_fb_fw_slot == 2u) ? 1u : 0u;
    default:                             return 0u;
    }
}

/**
 * @brief Model of the rtlnet_framebuf register writes: FW_TAKE and FW_RELEASE with the sticky FW_ERR, CNT_CLEAR.
 * @param off   Register offset.
 * @param value Value.
 * @return None.
 */
static void host_fb_write(uint32_t off, uint32_t value)
{
    if (off == RTLNET_FB_REG_STATUS) {
        g_fb_err &= ~(value & HOST_VID_ERR_FB);
    } else if (off == RTLNET_FB_REG_CTRL) {
        if ((value & RTLNET_FB_CTRL_FW_TAKE) != 0u) {
            if (g_vid_frames == 0u || g_fb_holds) {
                g_fb_err |= HOST_VID_ERR_FB;
            } else {
                g_fb_holds    = 1;
                g_fb_fw_slot  = host_vid_slot(g_vid_frames);
                g_fb_fw_frame = g_vid_frames;
                g_fb_fw_mode  = g_csi_mode;
                g_fb_takes++;
                host_vid_fill(g_fb_fw_slot, g_fb_fw_mode);
            }
        }
        if ((value & RTLNET_FB_CTRL_FW_RELEASE) != 0u) {
            if (!g_fb_holds) {
                g_fb_err |= HOST_VID_ERR_FB;
            } else {
                g_fb_holds = 0;
            }
        }
        if ((value & RTLNET_FB_CTRL_CNT_CLEAR) != 0u) {
            g_vid_base = g_vid_frames;
            g_fb_takes = 0u;
        }
    }
}

/**
 * @brief Held-slot state of the framebuf model, for the harness checks.
 * @return 1 while the firmware holds a slot.
 */
int host_model_video_fw_holds(void)
{
    return g_fb_holds;
}
static void   (*g_irq_handler[RTLNET_CPU_IRQ_COUNT])(void *);
static void    *g_irq_ref[RTLNET_CPU_IRQ_COUNT];
static uint32_t g_irq_enabled;
static uint32_t g_irq_lines;
static int      g_irq_masked;
static int      g_irq_in_deliver;
static uint32_t g_irq_delivered;
static uint32_t g_irq_acc_total;      /* register accesses made inside handler calls */
static uint32_t g_irq_acc_max;        /* the most in one handler call */

/**
 * @brief Mask the CPU interrupts (nesting safe).
 * @return 8 when they were unmasked (the RISC-V mstatus.MIE bit), 0 when already masked; for plat_irq_restore.
 */
uint32_t plat_irq_save(void)
{
    uint32_t prev = g_irq_masked ? 0x80u : 0u;
    g_irq_masked = 1;
    return prev;
}

/**
 * @brief Return to the state plat_irq_save found; unmasking delivers a pending interrupt.
 * @param state Value from plat_irq_save.
 * @return None.
 */
void plat_irq_restore(uint32_t state)
{
    if ((state & 0x80u) == 0u) {
        g_irq_masked = 0;
        host_irq_deliver();
    }
}

/**
 * @brief Connect a handler on an INTC input; the input stays masked.
 * @param input   INTC input.
 * @param handler Handler.
 * @param ref     Argument of the handler.
 * @return 0, or -1 for an input out of range.
 */
int plat_irq_attach(unsigned input, void (*handler)(void *), void *ref)
{
    if (input >= RTLNET_CPU_IRQ_COUNT || handler == NULL) {
        return -1;
    }
    g_irq_handler[input] = handler;
    g_irq_ref[input] = ref;
    return 0;
}

/**
 * @brief Unmask or mask an INTC input.
 * @param input INTC input.
 * @param on    1 unmask, 0 mask.
 * @return None.
 */
void plat_irq_enable(unsigned input, int on)
{
    if (input >= RTLNET_CPU_IRQ_COUNT) {
        return;
    }
    if (on != 0) {
        g_irq_enabled |= 1u << input;
        host_irq_deliver();
    } else {
        g_irq_enabled &= ~(1u << input);
    }
}

/**
 * @brief A model drives an input line.
 * @param input INTC input.
 * @param level 1 high, 0 low.
 * @return None.
 */
void host_irq_set_line(unsigned input, uint32_t level)
{
    if (input >= RTLNET_CPU_IRQ_COUNT) {
        return;
    }
    if (level != 0u) {
        g_irq_lines |= 1u << input;
    } else {
        g_irq_lines &= ~(1u << input);
    }
}

/**
 * @brief Call the handlers of the inputs that are high and enabled while the CPU interrupts are unmasked (level sensitive: a handler that leaves
 *        the line high is called again, at most 8 times per call).
 * @return None.
 */
void host_irq_deliver(void)
{
    if (g_irq_in_deliver) {
        return;
    }
    g_irq_in_deliver = 1;
    for (int n = 0; n < 8 && !g_irq_masked; n++) {
        unsigned in = RTLNET_CPU_IRQ_COUNT;
        for (unsigned i = 0; i < RTLNET_CPU_IRQ_COUNT; i++) {
            if (((g_irq_lines & g_irq_enabled) & (1u << i)) != 0u && g_irq_handler[i] != NULL) {
                in = i;
                break;
            }
        }
        if (in == RTLNET_CPU_IRQ_COUNT) {
            break;
        }
        g_irq_masked = 1;      /* the trap masks the CPU interrupts while the handler runs */
        g_irq_delivered++;
        {
            uint32_t a0 = g_reg_acc;
            g_irq_handler[in](g_irq_ref[in]);
            a0 = g_reg_acc - a0;
            g_irq_acc_total += a0;
            if (a0 > g_irq_acc_max) {
                g_irq_acc_max = a0;
            }
        }
        g_irq_masked = 0;
    }
    g_irq_in_deliver = 0;
}

/**
 * @brief Handler calls made so far.
 * @return Count.
 */
uint32_t host_irq_delivered(void)
{
    return g_irq_delivered;
}

/**
 * @brief Register accesses made inside interrupt handler calls.
 * @param calls Receives the handler calls.
 * @param total Receives the accesses summed over the calls.
 * @param max   Receives the most accesses in one call.
 * @return None.
 */
void host_irq_access_stats(uint32_t *calls, uint32_t *total, uint32_t *max)
{
    *calls = g_irq_delivered;
    *total = g_irq_acc_total;
    *max = g_irq_acc_max;
}

/**
 * @brief Write bytes into the DDR3 model without counting an arbiter access (the encoder model's DMA writes).
 * @param ddr_off Byte offset in the DDR3 window.
 * @param data    Bytes.
 * @param n       Count.
 * @return None.
 */
void host_ddr_poke(uint32_t ddr_off, const uint8_t *data, uint32_t n)
{
    for (uint32_t i = 0u; i < n; i++) {
        uintptr_t a = (uintptr_t)(RTLNET_PLAT_DDR_BASE + ((ddr_off + i) & ~3u));
        uint32_t *pg = host_ddr_page(a, 1);
        if (pg != NULL) {
            uint32_t sh = 8u * ((ddr_off + i) & 3u);
            uint32_t *w = &pg[host_ddr_word(a)];
            *w = (*w & ~(0xFFu << sh)) | ((uint32_t)data[i] << sh);
        }
    }
}


/* Firmware-visible ZCAM mode/PTS replace the old synthetic CSI register file. */
uint32_t rtlnet_host_reg_read32(uintptr_t addr)
{
    g_reg_acc++; host_h264_on_access();
    if(g_vid_on && addr>=RTLNET_PLAT_CSI2_BASE && addr<RTLNET_PLAT_CSI2_BASE+0x1000u) {
        switch(addr-RTLNET_PLAT_CSI2_BASE) {
        case RTLNET_ZCAM_REG_ID:return RTLNET_ZCAM_ID_VALUE;
        case RTLNET_ZCAM_REG_PTS_STEP:return g_csi_mode?6000u:3000u;
        case RTLNET_ZCAM_REG_MODE:return g_csi_mode;
        default:return 0u;
        }
    }
    if(g_vid_on && addr>=RTLNET_PLAT_S2MM_BASE && addr<RTLNET_PLAT_S2MM_BASE+0x1000u) return host_s2mm_read((uint32_t)(addr-RTLNET_PLAT_S2MM_BASE));
    if(g_vid_on && addr>=RTLNET_PLAT_FB_BASE && addr<RTLNET_PLAT_FB_BASE+0x1000u) return host_fb_read((uint32_t)(addr-RTLNET_PLAT_FB_BASE));
    if(host_h264_active() && addr>=RTLNET_PLAT_H264_BASE && addr<RTLNET_PLAT_H264_BASE+0x1000u) return host_h264_read((uint32_t)(addr-RTLNET_PLAT_H264_BASE));
    return 0u;
}
void rtlnet_host_reg_write32(uintptr_t addr,uint32_t v)
{
    g_reg_acc++; host_h264_on_access();
    if(addr==RTLNET_PLAT_CSI2_BASE+RTLNET_ZCAM_REG_MODE) {g_csi_mode=v;g_csi_period=v?66667u:33333u;}
    else if(g_vid_on && addr>=RTLNET_PLAT_S2MM_BASE && addr<RTLNET_PLAT_S2MM_BASE+0x1000u) host_s2mm_write((uint32_t)(addr-RTLNET_PLAT_S2MM_BASE),v);
    else if(g_vid_on && addr>=RTLNET_PLAT_FB_BASE && addr<RTLNET_PLAT_FB_BASE+0x1000u) host_fb_write((uint32_t)(addr-RTLNET_PLAT_FB_BASE),v);
    else if(host_h264_active() && addr>=RTLNET_PLAT_H264_BASE && addr<RTLNET_PLAT_H264_BASE+0x1000u) host_h264_write((uint32_t)(addr-RTLNET_PLAT_H264_BASE),v);
}
void plat_init(void)
{
    g_t0=clock(); memset(g_irq_handler,0,sizeof(g_irq_handler)); memset(g_irq_ref,0,sizeof(g_irq_ref));
    g_irq_enabled=0u; g_irq_masked=0;
}
int board_ddr_calibrated(void) {return g_ddr_cal;}
